script.setup:
const frag = `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 outColor;
uniform vec2 u_resolution;
uniform vec3 u_eye;
uniform vec3 u_target;
uniform float u_roughness;
uniform float u_radius;
uniform float u_grid;
uniform float u_exposure;

float sdScene(vec3 p) { return min(p.y, length(p-vec3(0.0,u_radius,0.0))-u_radius); }
vec2 march(vec3 ro,vec3 rd) {
 float t=0.0;
 for(int i=0;i<140;i++) {
  vec3 p=ro+rd*t;
  float sphere=length(p-vec3(0.0,u_radius,0.0))-u_radius;
  float d=min(p.y,sphere);
  if(d<0.0006*max(t,1.0)) return vec2(t,sphere<p.y?1.0:0.0);
  t+=d*0.92;
  if(t>160.0) break;
 }
 return vec2(-1.0,0.0);
}
vec3 sky(vec3 d) {
 float h=max(d.y,0.0);
 vec3 col=mix(vec3(0.48,0.58,0.70),vec3(0.055,0.12,0.22),pow(h,0.5));
 if(d.y<0.0) col=mix(vec3(0.48,0.58,0.70),vec3(0.055,0.075,0.10),clamp(-d.y*2.0,0.0,1.0));
 vec3 sun=normalize(vec3(-0.6,0.85,0.5));
 float s=max(dot(d,sun),0.0);
 col+=vec3(1.0,0.82,0.59)*pow(s,180.0)*2.3;
 col+=vec3(1.0,0.86,0.68)*pow(s,18.0)*0.14;
 float panel=exp(-pow((d.x+0.46)/0.24,8.0)-pow((d.y-0.55)/0.23,8.0));
 col+=vec3(1.0,0.92,0.80)*panel*1.9;
 float strip=exp(-pow((d.x-0.70)/0.065,6.0)-pow((d.y-0.32)/0.42,8.0));
 col+=vec3(0.57,0.77,1.0)*strip*1.4;
 return col;
}
float shadow(vec3 p,vec3 l) {
 float res=1.0,t=0.012;
 for(int i=0;i<48;i++) {
  float h=length(p+l*t-vec3(0,u_radius,0))-u_radius;
  res=min(res,12.0*h/t);
  t+=clamp(h,0.01,0.3);
  if(t>12.0) break;
 }
 return clamp(res,0.0,1.0);
}
vec3 floorColor(vec3 p,vec3 rd,float distance) {
 vec2 q=p.xz;
 float footprint=max(0.002,distance/u_resolution.y/max(abs(rd.y),0.045))*1.7;
 float checker=0.5-0.5*cos(3.14159265*q.x)*cos(3.14159265*q.y);
 float fade=exp(-footprint*2.8);
 vec3 col=mix(vec3(0.12,0.16,0.20),vec3(0.27,0.32,0.36),mix(0.5,checker,fade));
 vec2 cell=abs(fract(q+0.5)-0.5);
 float line=1.0-smoothstep(0.012,0.012+footprint,min(cell.x,cell.y));
 col=mix(col,col*0.64,line*u_grid*fade);
 vec3 l=normalize(vec3(-0.6,0.85,0.5));
 float sh=shadow(p+vec3(0,0.002,0),l);
 float contact=1.0-0.52*exp(-length(q)*length(q)/(u_radius*u_radius*0.85));
 col*=vec3(0.52,0.65,0.80)*0.6+vec3(1.0,0.9,0.76)*sh*0.85;
 col*=contact;
 vec3 refl=sky(reflect(rd,vec3(0,1,0)));
 float fres=0.025+0.10*pow(1.0-max(-rd.y,0.0),5.0);
 col=mix(col,refl,fres);
 return mix(col,sky(rd),1.0-exp(-distance*0.007));
}
vec3 secondary(vec3 ro,vec3 rd) {
 vec2 hit=march(ro,rd);
 if(hit.x<0.0) return sky(rd);
 vec3 p=ro+rd*hit.x;
 if(hit.y<0.5) return floorColor(p,rd,hit.x);
 return sky(reflect(rd,normalize(p-vec3(0,u_radius,0))));
}
float hash(vec2 p) { return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
void main() {
 vec2 uv=(2.0*gl_FragCoord.xy-u_resolution)/u_resolution.y;
 vec3 fw=normalize(u_target-u_eye);
 vec3 rt=normalize(cross(fw,vec3(0,1,0)));
 vec3 up=cross(rt,fw);
 vec3 rd=normalize(fw*1.95+rt*uv.x+up*uv.y);
 vec2 hit=march(u_eye,rd);
 vec3 col;
 if(hit.x<0.0) col=sky(rd);
 else {
  vec3 p=u_eye+rd*hit.x;
  if(hit.y<0.5) col=floorColor(p,rd,hit.x);
  else {
   vec3 n=normalize(p-vec3(0,u_radius,0));
   vec3 r=reflect(rd,n);
   vec3 tangent=normalize(cross(r,abs(r.y)<0.95?vec3(0,1,0):vec3(1,0,0)));
   vec3 bitangent=cross(r,tangent);
   vec3 ref=vec3(0);
   for(int i=0;i<7;i++) {
    float angle=float(i)*2.399963;
    float spread=u_roughness*u_roughness*sqrt(float(i)/6.0)*0.75;
    vec3 rr=normalize(r+spread*(cos(angle)*tangent+sin(angle)*bitangent));
    ref+=secondary(p+n*0.004,rr);
   }
   ref/=7.0;
   float fres=pow(1.0-max(dot(-rd,n),0.0),5.0);
   col=ref*mix(vec3(0.86,0.91,0.97),vec3(1),fres);
   col*=1.0-0.14*exp(-p.y*3.0/u_radius);
  }
 }
 col*=u_exposure;
 col=(col*(2.51*col+0.03))/(col*(2.43*col+0.59)+0.14);
 col=pow(clamp(col,0.0,1.0),vec3(1.0/2.2));
 col*=1.0-0.12*dot(v_uv-0.5,v_uv-0.5);
 col+=(hash(gl_FragCoord.xy)-0.5)/255.0;
 outColor=vec4(col,1.0);
}`;
ctx.state.program=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,frag);
ctx.state.camera=ctx.utils.createOrbitCamera({distance:7.2,theta:0.65,phi:1.16,target:[0,1,0]});
ctx.state.wheel=(e)=>{e.preventDefault();ctx.state.camera.zoom(e.deltaY*0.001);};
ctx.canvas.addEventListener('wheel',ctx.state.wheel,{passive:false});
